package riptide

import "fmt"

// Rollup is the one-per-PR summary emitted after a review.
type Rollup struct {
	Project  string
	Repo     string
	PR       int
	Findings int
}

// Key identifies the rollup for deduplication.
func (r Rollup) Key() string {
	return fmt.Sprintf("%s/%s#%d", r.Project, r.Repo, r.PR)
}

// Describe renders the rollup for a log line.
func Describe(rollup Rollup) string {
	if rollup.Findings == 0 {
		return rollup.Key() + ": no findings"
	}
	return fmt.Sprintf("%s: %d findings", rollup.Key(), rollup.Findings)
}
